-- Client doc 16 Nov (J1) — the lead section statuses: New, User Not Responding, Contacted, Interested, Under Review,
-- (quotation steps for the quotation services), Converted (set by the payment) and Unqualified. Lead "On Hold" moves to
-- Contacted and is switched off; lead "Cancelled" becomes Unqualified; lead "Paid" is now "Converted".
-- The client's final status lists and per-status email / WhatsApp templates (client docs 2026-10-20, 16 Nov 2026).
-- Generated by scripts/status-catalog-sql.ts from src/lib/service-status/catalog.ts + template-catalog.json.
ALTER TABLE "Booking" ADD COLUMN IF NOT EXISTS "resumeServiceStatusId" TEXT;
ALTER TABLE "NotificationTemplate" ADD COLUMN IF NOT EXISTS "heading" TEXT;
ALTER TABLE "NotificationTemplate" ADD COLUMN IF NOT EXISTS "ctaLabel" TEXT;
ALTER TABLE "NotificationTemplate" ADD COLUMN IF NOT EXISTS "ctaLink" TEXT;

