UPDATE "ServiceStatus" SET "systemEvent" = NULL WHERE "serviceType" = 'NEW_VISA' AND "scope" = 'LEAD';

UPDATE "ServiceStatus" SET "name" = 'New'
WHERE "id" = (
  SELECT "id" FROM "ServiceStatus" WHERE "serviceType" = 'NEW_VISA' AND "scope" = 'LEAD' AND "name" IN ('Quotation Created', 'Quotation Accepted', 'Payment Pending')
  ORDER BY array_position(ARRAY['Quotation Created', 'Quotation Accepted', 'Payment Pending']::text[], "name") LIMIT 1
) AND NOT EXISTS (SELECT 1 FROM "ServiceStatus" WHERE "serviceType" = 'NEW_VISA' AND "scope" = 'LEAD' AND "name" = 'New');

