UPDATE "ServiceStatus" SET "active" = false, "systemEvent" = NULL, "notificationEvent" = NULL WHERE "serviceType" = 'VISA_EXTENSION' AND "scope" = 'LEAD' AND "name" NOT IN ('New', 'User Not Responding', 'Contacted', 'Interested', 'Eligibility Review', 'Not Eligible', 'Quotation Sent', 'Quotation Accepted', 'Payment Pending', 'Converted', 'Unqualified');

INSERT INTO "ServiceStatusTransition" ("id", "fromStatusId", "toStatusId")
SELECT 'sst_' || md5(f."id" || '>' || t."id"), f."id", t."id"
FROM (VALUES
  ('New', 'User Not Responding'),
  ('New', 'Contacted'),
  ('New', 'Interested'),
  ('New', 'Eligibility Review'),
  ('New', 'Not Eligible'),
  ('New', 'Quotation Sent'),
  ('New', 'Quotation Accepted'),
  ('New', 'Payment Pending'),
  ('New', 'Converted'),
  ('New', 'Unqualified'),
  ('User Not Responding', 'New'),
  ('User Not Responding', 'Contacted'),
  ('User Not Responding', 'Interested'),
  ('User Not Responding', 'Eligibility Review'),
  ('User Not Responding', 'Quotation Sent'),
  ('User Not Responding', 'Quotation Accepted'),
  ('User Not Responding', 'Payment Pending'),
  ('Contacted', 'User Not Responding'),
  ('Contacted', 'Interested'),
  ('Contacted', 'Eligibility Review'),
  ('Contacted', 'Not Eligible'),
  ('Contacted', 'Quotation Sent'),
  ('Contacted', 'Quotation Accepted'),
  ('Contacted', 'Payment Pending'),
  ('Contacted', 'Converted'),
  ('Contacted', 'Unqualified'),
  ('Interested', 'User Not Responding'),
  ('Interested', 'Eligibility Review'),
  ('Interested', 'Not Eligible'),
  ('Interested', 'Quotation Sent'),
  ('Interested', 'Quotation Accepted'),
  ('Interested', 'Payment Pending'),
  ('Interested', 'Converted'),
  ('Interested', 'Unqualified'),
  ('Eligibility Review', 'User Not Responding'),
  ('Eligibility Review', 'Not Eligible'),
  ('Eligibility Review', 'Quotation Sent'),
  ('Eligibility Review', 'Quotation Accepted'),
  ('Eligibility Review', 'Payment Pending'),
  ('Eligibility Review', 'Converted'),
  ('Eligibility Review', 'Unqualified'),
  ('Quotation Sent', 'User Not Responding'),
  ('Quotation Sent', 'Quotation Accepted'),
  ('Quotation Sent', 'Payment Pending'),
  ('Quotation Sent', 'Converted'),
  ('Quotation Sent', 'Unqualified'),
  ('Quotation Accepted', 'User Not Responding'),
  ('Quotation Accepted', 'Payment Pending'),
  ('Quotation Accepted', 'Converted'),
  ('Quotation Accepted', 'Unqualified'),
  ('Payment Pending', 'User Not Responding'),
  ('Payment Pending', 'Converted'),
  ('Payment Pending', 'Unqualified')
) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'VISA_EXTENSION' AND f."scope" = 'LEAD' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'VISA_EXTENSION' AND t."scope" = 'LEAD' AND t."name" = p."toName"
ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

