INSERT INTO "ServiceStatusTransition" ("id", "fromStatusId", "toStatusId")
SELECT 'sst_' || md5(f."id" || '>' || t."id"), f."id", t."id"
FROM (VALUES
  ('New', 'User Not Responding'),
  ('New', 'Contacted'),
  ('New', 'Interested'),
  ('New', 'Under Review'),
  ('New', 'Converted'),
  ('New', 'Unqualified'),
  ('User Not Responding', 'New'),
  ('User Not Responding', 'Contacted'),
  ('User Not Responding', 'Interested'),
  ('User Not Responding', 'Under Review'),
  ('Contacted', 'User Not Responding'),
  ('Contacted', 'Interested'),
  ('Contacted', 'Under Review'),
  ('Contacted', 'Converted'),
  ('Contacted', 'Unqualified'),
  ('Interested', 'User Not Responding'),
  ('Interested', 'Under Review'),
  ('Interested', 'Converted'),
  ('Interested', 'Unqualified'),
  ('Under Review', 'User Not Responding'),
  ('Under Review', 'Converted'),
  ('Under Review', 'Unqualified')
) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'OTB' AND f."scope" = 'LEAD' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'OTB' AND t."scope" = 'LEAD' AND t."name" = p."toName"
ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

