) AS p("fromName", "toName")
JOIN "ServiceStatus" f ON f."serviceType" = 'FLIGHT_SPECIAL_FARE' AND f."scope" = 'BOOKING' AND f."name" = p."fromName"
JOIN "ServiceStatus" t ON t."serviceType" = 'FLIGHT_SPECIAL_FARE' AND t."scope" = 'BOOKING' AND t."name" = p."toName"
ON CONFLICT ("fromStatusId", "toStatusId") DO NOTHING;

