INSERT INTO "NotificationTemplate" ("id", "event", "channel", "subject", "body", "active", "heading", "ctaLabel", "ctaLink", "createdAt", "updatedAt")
VALUES ('nt_' || md5('SF_15/EMAIL'), 'SF_15', 'EMAIL', 'Your flight ticket is issued — {{booking_id}}', 'Hi {{customer_name}},

Your ticket for {{booking_id}} has been issued.
Passenger(s): {{passenger_names}}
Route: {{origin}} → {{destination}} | Date: {{travel_date}}
Flight: {{airline_flight_number}}
PNR: {{pnr}}
Baggage: {{baggage}}
Important Information
Airport Reporting: Arrive at least 2 hours before domestic flights and 4 hours before international flights.
Travel Documents: Carry a valid government-issued photo ID for domestic travel. International travellers must carry a valid passport, applicable visas and transit documents.
Terminal & Timings: Confirm the departure terminal and latest flight status with the airline. All timings are local to the respective airports.
Web Check-in: Complete airline web check-in and obtain your boarding pass where required.
Baggage: Check the baggage allowance mentioned on your ticket.
Changes & Refunds: Cancellations, refunds and rescheduling are subject to airline fare rules and applicable charges.
Travel Requirements: Passengers are responsible for meeting visa, transit, immigration and OTB requirements, where applicable.
Ticket Verification Disclaimer: Please check all ticket details, including passenger names, travel dates, flight timings and routes, immediately upon receipt. Report any errors to TripNexio within 12 hours of ticket issuance. Later corrections will be subject to airline rules, availability and applicable charges.

Have a safe and pleasant journey with TripNexio!', true, NULL, 'Download Ticket', 'ticket_download_link', now(), now())
ON CONFLICT ("event", "channel") DO NOTHING;

INSERT INTO "NotificationTemplate" ("id", "event", "channel", "subject", "body", "active", "heading", "ctaLabel", "ctaLink", "createdAt", "updatedAt")
VALUES ('nt_' || md5('SF_15/WHATSAPP'), 'SF_15', 'WHATSAPP', NULL, 'Hi {{customer_name}},

Your ticket for {{booking_id}} has been issued. Route: {{origin}} → {{destination}} | Date: {{travel_date}} | Flight: {{airline_flight_number}} | PNR: {{pnr}} | Baggage: {{baggage}}. Download and check all details immediately; report errors within 12 hours. Arrive at least 2 hours before domestic flights and 4 hours before international flights. Carry required ID/passport, visas and transit documents; confirm terminal, flight status, check-in and baggage rules with the airline. Passengers are responsible for visa, transit, immigration and OTB requirements where applicable. Have a safe and pleasant journey with TripNexio!', true, NULL, 'Download Ticket', 'ticket_download_link', now(), now())
ON CONFLICT ("event", "channel") DO NOTHING;

